-- M-4c : 원본(출처) DB 스키마·테이블 매핑 (docs/source-mapping-m4c.md, 정책 docs/m4-foundation.md 5장)
--  1) TB_PRJ_SRC_CNTN : 프로젝트의 가져오기 기준 연결 (프로젝트마다 하나)
--     TB_SRC_SCHM_MPNG : 원본 스키마 ↔ 모델 스키마 (기준 연결 안에서 1:1)
--     TB_SRC_TBL_MPNG  : 원본 TABLE ↔ 모델 TABLE (기준 연결 안에서 1:1)
--     원본 쪽(TB_SRC_*)은 일련번호 값만 둔다 (모듈·생명주기가 달라 FK 를 걸지 않는다 : 연결 삭제는 이벤트로 정리).
--     모델 쪽은 FK + ON DELETE SET NULL : 모델 스키마·테이블을 지워도 매핑 행은 "모델 없음" 으로 남아 사용자가 해제한다.
--     매핑 확정 시점의 원본 식별 정보(비교 경로·비교 이름·생성 차수)와 반영 순서를 함께 저장한다. PostgreSQL OID 는 저장하지 않는다.
--  2) 예제 (데이터 사전 용어 → 물리 → 논리 → 매핑, 자체 인덱스) : 프로젝트 LEXORMA 의 예제가 있을 때만 넣는다.
-- 이 파일부터 증분 마이그레이션이다 : 이미 적용된 V0·V1 은 고치지 않는다 (개발 DB 를 다시 만들지 않는다).


create sequence SQ_PRJ_SRC_CNTN start with 1 increment by 50;
create sequence SQ_SRC_SCHM_MPNG start with 1 increment by 50;
create sequence SQ_SRC_TBL_MPNG start with 1 increment by 50;

-- 프로젝트의 가져오기 기준 원본 연결 (없으면 기준 연결이 없다). 매핑 변경은 이 행을 잠가 프로젝트 안에서 한 번에 하나씩 한다
create table TB_PRJ_SRC_CNTN (
    PRJ_SRC_CNTN_SN bigint not null,
    PRJ_SN bigint not null,
    SRC_CNTN_SN bigint not null,
    REG_DT timestamp(6),
    MDFCN_DT timestamp(6),
    RGTR_ID varchar(255),
    MDFR_ID varchar(255),
    constraint PK_PRJ_SRC_CNTN primary key (PRJ_SRC_CNTN_SN)
);
-- 원본 스키마 ↔ 모델 스키마. PATH_CN·SCHM_NM·CRT_CYCL·RFLT_ORD : 확정할 때의 원본 식별 정보와 반영 순서
create table TB_SRC_SCHM_MPNG (
    SRC_SCHM_MPNG_SN bigint not null,
    PRJ_SN bigint not null,
    SRC_CNTN_SN bigint not null,
    SRC_SCHM_SN bigint not null,
    PATH_CN varchar(1000) not null,
    SCHM_NM varchar(255) not null,
    CRT_CYCL integer not null,
    RFLT_ORD integer not null,
    SCHM_SN bigint,
    REG_DT timestamp(6),
    MDFCN_DT timestamp(6),
    RGTR_ID varchar(255),
    MDFR_ID varchar(255),
    constraint PK_SRC_SCHM_MPNG primary key (SRC_SCHM_MPNG_SN)
);
-- 원본 TABLE ↔ 모델 TABLE. CMPR_NM : 확정할 때의 원본 비교 이름 (DBMS 규칙으로 정규화)
create table TB_SRC_TBL_MPNG (
    SRC_TBL_MPNG_SN bigint not null,
    PRJ_SN bigint not null,
    SRC_CNTN_SN bigint not null,
    SRC_SCHM_SN bigint not null,
    SRC_TBL_SN bigint not null,
    PATH_CN varchar(1000) not null,
    CMPR_NM varchar(255) not null,
    CRT_CYCL integer not null,
    RFLT_ORD integer not null,
    TBL_SN bigint,
    REG_DT timestamp(6),
    MDFCN_DT timestamp(6),
    RGTR_ID varchar(255),
    MDFR_ID varchar(255),
    constraint PK_SRC_TBL_MPNG primary key (SRC_TBL_MPNG_SN)
);

create unique index UX_PRJ_SRC_CNTN_01 on TB_PRJ_SRC_CNTN (PRJ_SN);
create index IX_PRJ_SRC_CNTN_01 on TB_PRJ_SRC_CNTN (SRC_CNTN_SN);
create unique index UX_SRC_SCHM_MPNG_01 on TB_SRC_SCHM_MPNG (SRC_CNTN_SN, SRC_SCHM_SN);
create unique index UX_SRC_SCHM_MPNG_02 on TB_SRC_SCHM_MPNG (SRC_CNTN_SN, SCHM_SN);
create index IX_SRC_SCHM_MPNG_01 on TB_SRC_SCHM_MPNG (PRJ_SN);
create index IX_SRC_SCHM_MPNG_02 on TB_SRC_SCHM_MPNG (SCHM_SN);
create unique index UX_SRC_TBL_MPNG_01 on TB_SRC_TBL_MPNG (SRC_CNTN_SN, SRC_TBL_SN);
create unique index UX_SRC_TBL_MPNG_02 on TB_SRC_TBL_MPNG (SRC_CNTN_SN, TBL_SN);
create index IX_SRC_TBL_MPNG_01 on TB_SRC_TBL_MPNG (PRJ_SN);
create index IX_SRC_TBL_MPNG_02 on TB_SRC_TBL_MPNG (TBL_SN);

-- 모델 쪽만 FK : 모델 스키마·테이블을 지우면 매핑은 남고 모델 쪽이 비어 "모델 없음" 이 된다
alter table TB_SRC_SCHM_MPNG add constraint FK_SRC_SCHM_MPNG_01 foreign key (SCHM_SN) references TB_SCHM on delete set null;
alter table TB_SRC_TBL_MPNG add constraint FK_SRC_TBL_MPNG_01 foreign key (TBL_SN) references TB_TBL on delete set null;


comment on table TB_PRJ_SRC_CNTN is '프로젝트 출처 접속';
comment on column TB_PRJ_SRC_CNTN.PRJ_SRC_CNTN_SN is '프로젝트 출처 접속 일련번호';
comment on column TB_PRJ_SRC_CNTN.PRJ_SN is '프로젝트 일련번호';
comment on column TB_PRJ_SRC_CNTN.SRC_CNTN_SN is '출처 접속 일련번호';
comment on column TB_PRJ_SRC_CNTN.REG_DT is '등록 일시';
comment on column TB_PRJ_SRC_CNTN.MDFCN_DT is '수정 일시';
comment on column TB_PRJ_SRC_CNTN.RGTR_ID is '등록자 아이디';
comment on column TB_PRJ_SRC_CNTN.MDFR_ID is '수정자 아이디';
comment on table TB_SRC_SCHM_MPNG is '출처 스키마 매핑';
comment on column TB_SRC_SCHM_MPNG.SRC_SCHM_MPNG_SN is '출처 스키마 매핑 일련번호';
comment on column TB_SRC_SCHM_MPNG.PRJ_SN is '프로젝트 일련번호';
comment on column TB_SRC_SCHM_MPNG.SRC_CNTN_SN is '출처 접속 일련번호';
comment on column TB_SRC_SCHM_MPNG.SRC_SCHM_SN is '출처 스키마 일련번호';
comment on column TB_SRC_SCHM_MPNG.PATH_CN is '경로 내용';
comment on column TB_SRC_SCHM_MPNG.SCHM_NM is '스키마 명';
comment on column TB_SRC_SCHM_MPNG.CRT_CYCL is '생성 차수';
comment on column TB_SRC_SCHM_MPNG.RFLT_ORD is '반영 순서';
comment on column TB_SRC_SCHM_MPNG.SCHM_SN is '스키마 일련번호';
comment on column TB_SRC_SCHM_MPNG.REG_DT is '등록 일시';
comment on column TB_SRC_SCHM_MPNG.MDFCN_DT is '수정 일시';
comment on column TB_SRC_SCHM_MPNG.RGTR_ID is '등록자 아이디';
comment on column TB_SRC_SCHM_MPNG.MDFR_ID is '수정자 아이디';
comment on table TB_SRC_TBL_MPNG is '출처 테이블 매핑';
comment on column TB_SRC_TBL_MPNG.SRC_TBL_MPNG_SN is '출처 테이블 매핑 일련번호';
comment on column TB_SRC_TBL_MPNG.PRJ_SN is '프로젝트 일련번호';
comment on column TB_SRC_TBL_MPNG.SRC_CNTN_SN is '출처 접속 일련번호';
comment on column TB_SRC_TBL_MPNG.SRC_SCHM_SN is '출처 스키마 일련번호';
comment on column TB_SRC_TBL_MPNG.SRC_TBL_SN is '출처 테이블 일련번호';
comment on column TB_SRC_TBL_MPNG.PATH_CN is '경로 내용';
comment on column TB_SRC_TBL_MPNG.CMPR_NM is '비교 명';
comment on column TB_SRC_TBL_MPNG.CRT_CYCL is '생성 차수';
comment on column TB_SRC_TBL_MPNG.RFLT_ORD is '반영 순서';
comment on column TB_SRC_TBL_MPNG.TBL_SN is '테이블 일련번호';
comment on column TB_SRC_TBL_MPNG.REG_DT is '등록 일시';
comment on column TB_SRC_TBL_MPNG.MDFCN_DT is '수정 일시';
comment on column TB_SRC_TBL_MPNG.RGTR_ID is '등록자 아이디';
comment on column TB_SRC_TBL_MPNG.MDFR_ID is '수정자 아이디';

-- ---------- 예제 : 데이터 사전 (새 단어 뷰·정의, 용어·용어 단어). 같은 이름이 이미 있으면 넣지 않는다 ----------
insert into TB_STD_TRM(STD_TRM_SN, PRJ_SN, ENCT_CYCL, TRM_NM, TRM_EXPLN, TRM_ENG_ABBR_NM, PBADMS_STD_CD_NM, JRSDC_INST_NM, STD_DMN_SN, APRV_YN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_STD_TRM'), 0, 1, '프로젝트_출처_접속_일련번호', '프로젝트 출처 접속(가져오기 기준 연결) 일련번호.', 'PRJ_SRC_CNTN_SN', null, null, d.STD_DMN_SN, true, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_STD_DMN d where d.PRJ_SN = 0 and d.DMN_NM = '일련번호L' and not exists (select 1 from TB_STD_TRM where PRJ_SN = 0 and TRM_NM = '프로젝트_출처_접속_일련번호');
insert into TB_STD_TRM_WORD(STD_TRM_WORD_SN, STD_TRM_SN, STD_WORD_SN, SORT_ORD, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_STD_TRM_WORD'), t.STD_TRM_SN, w.STD_WORD_SN, 1, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_STD_TRM t join TB_STD_WORD w on w.PRJ_SN = 0 and w.WORD_NM = '프로젝트' where t.PRJ_SN = 0 and t.TRM_NM = '프로젝트_출처_접속_일련번호' and not exists (select 1 from TB_STD_TRM_WORD x where x.STD_TRM_SN = t.STD_TRM_SN and x.SORT_ORD = 1);
insert into TB_STD_TRM_WORD(STD_TRM_WORD_SN, STD_TRM_SN, STD_WORD_SN, SORT_ORD, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_STD_TRM_WORD'), t.STD_TRM_SN, w.STD_WORD_SN, 2, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_STD_TRM t join TB_STD_WORD w on w.PRJ_SN = 0 and w.WORD_NM = '출처' where t.PRJ_SN = 0 and t.TRM_NM = '프로젝트_출처_접속_일련번호' and not exists (select 1 from TB_STD_TRM_WORD x where x.STD_TRM_SN = t.STD_TRM_SN and x.SORT_ORD = 2);
insert into TB_STD_TRM_WORD(STD_TRM_WORD_SN, STD_TRM_SN, STD_WORD_SN, SORT_ORD, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_STD_TRM_WORD'), t.STD_TRM_SN, w.STD_WORD_SN, 3, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_STD_TRM t join TB_STD_WORD w on w.PRJ_SN = 0 and w.WORD_NM = '접속' where t.PRJ_SN = 0 and t.TRM_NM = '프로젝트_출처_접속_일련번호' and not exists (select 1 from TB_STD_TRM_WORD x where x.STD_TRM_SN = t.STD_TRM_SN and x.SORT_ORD = 3);
insert into TB_STD_TRM_WORD(STD_TRM_WORD_SN, STD_TRM_SN, STD_WORD_SN, SORT_ORD, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_STD_TRM_WORD'), t.STD_TRM_SN, w.STD_WORD_SN, 4, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_STD_TRM t join TB_STD_WORD w on w.PRJ_SN = 0 and w.WORD_NM = '일련번호' where t.PRJ_SN = 0 and t.TRM_NM = '프로젝트_출처_접속_일련번호' and not exists (select 1 from TB_STD_TRM_WORD x where x.STD_TRM_SN = t.STD_TRM_SN and x.SORT_ORD = 4);
insert into TB_STD_TRM(STD_TRM_SN, PRJ_SN, ENCT_CYCL, TRM_NM, TRM_EXPLN, TRM_ENG_ABBR_NM, PBADMS_STD_CD_NM, JRSDC_INST_NM, STD_DMN_SN, APRV_YN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_STD_TRM'), 0, 1, '출처_스키마_매핑_일련번호', '출처 스키마 매핑 일련번호.', 'SRC_SCHM_MPNG_SN', null, null, d.STD_DMN_SN, true, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_STD_DMN d where d.PRJ_SN = 0 and d.DMN_NM = '일련번호L' and not exists (select 1 from TB_STD_TRM where PRJ_SN = 0 and TRM_NM = '출처_스키마_매핑_일련번호');
insert into TB_STD_TRM_WORD(STD_TRM_WORD_SN, STD_TRM_SN, STD_WORD_SN, SORT_ORD, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_STD_TRM_WORD'), t.STD_TRM_SN, w.STD_WORD_SN, 1, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_STD_TRM t join TB_STD_WORD w on w.PRJ_SN = 0 and w.WORD_NM = '출처' where t.PRJ_SN = 0 and t.TRM_NM = '출처_스키마_매핑_일련번호' and not exists (select 1 from TB_STD_TRM_WORD x where x.STD_TRM_SN = t.STD_TRM_SN and x.SORT_ORD = 1);
insert into TB_STD_TRM_WORD(STD_TRM_WORD_SN, STD_TRM_SN, STD_WORD_SN, SORT_ORD, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_STD_TRM_WORD'), t.STD_TRM_SN, w.STD_WORD_SN, 2, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_STD_TRM t join TB_STD_WORD w on w.PRJ_SN = 0 and w.WORD_NM = '스키마' where t.PRJ_SN = 0 and t.TRM_NM = '출처_스키마_매핑_일련번호' and not exists (select 1 from TB_STD_TRM_WORD x where x.STD_TRM_SN = t.STD_TRM_SN and x.SORT_ORD = 2);
insert into TB_STD_TRM_WORD(STD_TRM_WORD_SN, STD_TRM_SN, STD_WORD_SN, SORT_ORD, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_STD_TRM_WORD'), t.STD_TRM_SN, w.STD_WORD_SN, 3, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_STD_TRM t join TB_STD_WORD w on w.PRJ_SN = 0 and w.WORD_NM = '매핑' where t.PRJ_SN = 0 and t.TRM_NM = '출처_스키마_매핑_일련번호' and not exists (select 1 from TB_STD_TRM_WORD x where x.STD_TRM_SN = t.STD_TRM_SN and x.SORT_ORD = 3);
insert into TB_STD_TRM_WORD(STD_TRM_WORD_SN, STD_TRM_SN, STD_WORD_SN, SORT_ORD, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_STD_TRM_WORD'), t.STD_TRM_SN, w.STD_WORD_SN, 4, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_STD_TRM t join TB_STD_WORD w on w.PRJ_SN = 0 and w.WORD_NM = '일련번호' where t.PRJ_SN = 0 and t.TRM_NM = '출처_스키마_매핑_일련번호' and not exists (select 1 from TB_STD_TRM_WORD x where x.STD_TRM_SN = t.STD_TRM_SN and x.SORT_ORD = 4);
insert into TB_STD_TRM(STD_TRM_SN, PRJ_SN, ENCT_CYCL, TRM_NM, TRM_EXPLN, TRM_ENG_ABBR_NM, PBADMS_STD_CD_NM, JRSDC_INST_NM, STD_DMN_SN, APRV_YN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_STD_TRM'), 0, 1, '출처_테이블_매핑_일련번호', '출처 테이블 매핑 일련번호.', 'SRC_TBL_MPNG_SN', null, null, d.STD_DMN_SN, true, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_STD_DMN d where d.PRJ_SN = 0 and d.DMN_NM = '일련번호L' and not exists (select 1 from TB_STD_TRM where PRJ_SN = 0 and TRM_NM = '출처_테이블_매핑_일련번호');
insert into TB_STD_TRM_WORD(STD_TRM_WORD_SN, STD_TRM_SN, STD_WORD_SN, SORT_ORD, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_STD_TRM_WORD'), t.STD_TRM_SN, w.STD_WORD_SN, 1, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_STD_TRM t join TB_STD_WORD w on w.PRJ_SN = 0 and w.WORD_NM = '출처' where t.PRJ_SN = 0 and t.TRM_NM = '출처_테이블_매핑_일련번호' and not exists (select 1 from TB_STD_TRM_WORD x where x.STD_TRM_SN = t.STD_TRM_SN and x.SORT_ORD = 1);
insert into TB_STD_TRM_WORD(STD_TRM_WORD_SN, STD_TRM_SN, STD_WORD_SN, SORT_ORD, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_STD_TRM_WORD'), t.STD_TRM_SN, w.STD_WORD_SN, 2, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_STD_TRM t join TB_STD_WORD w on w.PRJ_SN = 0 and w.WORD_NM = '테이블' where t.PRJ_SN = 0 and t.TRM_NM = '출처_테이블_매핑_일련번호' and not exists (select 1 from TB_STD_TRM_WORD x where x.STD_TRM_SN = t.STD_TRM_SN and x.SORT_ORD = 2);
insert into TB_STD_TRM_WORD(STD_TRM_WORD_SN, STD_TRM_SN, STD_WORD_SN, SORT_ORD, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_STD_TRM_WORD'), t.STD_TRM_SN, w.STD_WORD_SN, 3, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_STD_TRM t join TB_STD_WORD w on w.PRJ_SN = 0 and w.WORD_NM = '매핑' where t.PRJ_SN = 0 and t.TRM_NM = '출처_테이블_매핑_일련번호' and not exists (select 1 from TB_STD_TRM_WORD x where x.STD_TRM_SN = t.STD_TRM_SN and x.SORT_ORD = 3);
insert into TB_STD_TRM_WORD(STD_TRM_WORD_SN, STD_TRM_SN, STD_WORD_SN, SORT_ORD, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_STD_TRM_WORD'), t.STD_TRM_SN, w.STD_WORD_SN, 4, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_STD_TRM t join TB_STD_WORD w on w.PRJ_SN = 0 and w.WORD_NM = '일련번호' where t.PRJ_SN = 0 and t.TRM_NM = '출처_테이블_매핑_일련번호' and not exists (select 1 from TB_STD_TRM_WORD x where x.STD_TRM_SN = t.STD_TRM_SN and x.SORT_ORD = 4);

-- ---------- 예제 : 물리 모델 (테이블·컬럼·참조 관계). 같은 이름의 테이블이 이미 있으면 그 테이블은 넣지 않는다 ----------
