-- 참조 테이블명 → REF_COLUMN 관계 (V1·V3 의 예제와 같은 방식). 관계 이름 = 실제 FK 제약조건 이름
insert into TB_TBL_REL(REL_SN, PRJ_SN, ORGNL_TBL_SN, TRGT_TBL_SN, REL_NM, REL_TYPE_CD, REL_SRC_CD, DRVN_COL_SN, APRV_YN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_TBL_REL'), 0, c.TBL_SN, t.TBL_SN, 'FK_SRC_SCHM_MPNG_01', 'FK', 'REF_COLUMN', c.COL_SN, true, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_COL c join TB_TBL t on t.PRJ_SN = 0 and t.TBL_NM = 'TB_SCHM' where c.PRJ_SN = 0 and c.TBL_NM = 'TB_SRC_SCHM_MPNG' and c.COL_NM = 'SCHM_SN' and not exists (select 1 from TB_TBL_REL r where r.DRVN_COL_SN = c.COL_SN);
insert into TB_TBL_REL_COL(REL_COL_SN, REL_SN, ORGNL_COL_SN, TRGT_COL_SN, COL_ORD) select nextval('SQ_TBL_REL_COL'), r.REL_SN, r.DRVN_COL_SN, p.COL_SN, 1 from TB_TBL_REL r join TB_COL p on p.PRJ_SN = 0 and p.TBL_NM = 'TB_SCHM' and p.COL_NM = 'SCHM_SN' where r.PRJ_SN = 0 and r.REL_NM = 'FK_SRC_SCHM_MPNG_01' and r.DRVN_COL_SN = (select COL_SN from TB_COL where PRJ_SN = 0 and TBL_NM = 'TB_SRC_SCHM_MPNG' and COL_NM = 'SCHM_SN') and not exists (select 1 from TB_TBL_REL_COL x where x.REL_SN = r.REL_SN);
