insert into TB_TBL_REL_COL(REL_COL_SN, REL_SN, ORGNL_COL_SN, TRGT_COL_SN, COL_ORD) select nextval('SQ_TBL_REL_COL'), r.REL_SN, r.DRVN_COL_SN, p.COL_SN, 1 from TB_TBL_REL r join TB_COL p on p.PRJ_SN = 0 and p.TBL_NM = 'TB_TBL' and p.COL_NM = 'TBL_SN' where r.PRJ_SN = 0 and r.REL_NM = 'FK_SRC_TBL_MPNG_01' and r.DRVN_COL_SN = (select COL_SN from TB_COL where PRJ_SN = 0 and TBL_NM = 'TB_SRC_TBL_MPNG' and COL_NM = 'TBL_SN') and not exists (select 1 from TB_TBL_REL_COL x where x.REL_SN = r.REL_SN);

